<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentAllowController;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentListController;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentCreateController;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentRetrieveController;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentUpdateController;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driver\Rest\UserRoleAssignmentDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Service\Visibility\UserRoleAssignmentRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Policy\Filter\TenantAccessible;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driven\UserRoleAssignmentCommandRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Infrastructure\Driven\UserRoleAssignmentQueryRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentCommandRepositoryGateway;

class UserRoleAssignmentPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserRoleAssignmentQueryRepositoryGateway::class] = \DI\autowire(UserRoleAssignmentQueryRepositoryAdapter::class);
        $def[UserRoleAssignmentCommandRepositoryGateway::class] = \DI\autowire(UserRoleAssignmentCommandRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/user-role-assignment', [$this, 'setRoutesForUserRoleAssignment']);
        $collector->group('/api/me/acl/access/user-role-assignment', [$this, 'setRoutesForUserRoleAssignmentAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(UserRoleAssignmentRestrictFilterToVisibility::class, TenantAccessible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("user-role-assignment", "list", "READ");
            $handler->registerResourceAction("user-role-assignment", "create", "WRITE");
            $handler->registerResourceAction("user-role-assignment", "retrieve", "READ");
            $handler->registerResourceAction("user-role-assignment", "update", "WRITE");
            $handler->registerResourceAction("user-role-assignment", "delete", "WRITE");

            $handler->registerResourceAttribute("user-role-assignment", "user", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignment", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignment", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignment", "roles", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignment", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForUserRoleAssignmentAcl(RouteCollectorProxy $userRoleAssignmentGroup): void
    {
        $userRoleAssignmentGroup->get('', [UserRoleAssignmentAllowController::class, 'genericAllow']);
        $userRoleAssignmentGroup->get('/{uid}', [UserRoleAssignmentAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForUserRoleAssignment(RouteCollectorProxy $userRoleAssignmentGroup): void
    {
        $userRoleAssignmentGroup->get('', [UserRoleAssignmentListController::class, 'list']);
        $userRoleAssignmentGroup->post('', [UserRoleAssignmentCreateController::class, 'create']);
        $userRoleAssignmentGroup->get('/{uid}', [UserRoleAssignmentRetrieveController::class, 'retrieve']);
        $userRoleAssignmentGroup->put('/{uid}', [UserRoleAssignmentUpdateController::class, 'update']);
        $userRoleAssignmentGroup->delete('/{uid}', [UserRoleAssignmentDeleteController::class, 'delete']);
        $userRoleAssignmentGroup->delete('', [UserRoleAssignmentDeleteController::class, 'deleteAllForQuery']);
        $userRoleAssignmentGroup->get('/~/delete-status/{uid}', [UserRoleAssignmentDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
